            // TODO API_TEST_START
            net.coobird.thumbnailator.makers.ThumbnailMaker maker = new net.coobird.thumbnailator.makers.ScaledThumbnailMaker(0.5);

            // Set a specific non-default image type first
            maker.imageType(java.awt.image.BufferedImage.TYPE_INT_ARGB_PRE);

            // Revert to the default image type
            net.coobird.thumbnailator.makers.ThumbnailMaker returnedMaker = maker.defaultImageType();

            // Execute the maker to materialize the result
            java.awt.image.BufferedImage result = returnedMaker.make(sourceImage);

            assert returnedMaker == maker : "Expected defaultImageType() to return the same ThumbnailMaker instance for chaining";
            assert result != null : "Expected make() to return a valid BufferedImage";
            assert result.getWidth() > 0 && result.getHeight() > 0 : "Expected resulting image to have valid dimensions";

            System.out.println("__CHECK__ defaultImageType " + result.getType());
            // TODO API_TEST_END
            System.out.println("__DONE__");
        } catch (Throwable exc) {
            System.err.println("__RUN_ERR__ " + exc.getClass().getSimpleName()
                    + ": " + exc.getMessage());
            exc.printStackTrace(System.err);
            System.exit(1);
        }
    }
